#!/usr/bin/env bash
# End to end (ctest: e2e_asm_regen): assembler compiles use the client caches, and inputs the build
# regenerates with identical content (kbuild: av_permissions.h, crc32table.h, *.mod.c, the kallsyms .S files) are
# answered by the wrapper's direct path. Every step is `make clean && make` with opticc and, in a reference copy that
# saw the same edits, with the plain compiler; every object and dependency file must be byte-identical.
#   a.S    assembler with cpp, includes defs.h, kbuild's -Wp,-MMD dependency file      cached (direct hits)
#   g.S    generated by the build (identical content every time), no dependency file   cached (direct hits)
#   b.c    includes gen.h, regenerated by the build with IDENTICAL content             direct hits
#   c.c    includes gen2.h, regenerated with DIFFERENT content every build             always a miss (content)
#   d.c    plain                                                                       direct hits
#   bin.S  .incbin of blob.bin                                                         never cached (store-skipped)
#   inc.S  .include of part.inc (an assembler include: in no dependency file)          never cached (store-skipped)
# The generator rules wait 50 ms after writing (as a real build's next command takes a few ms to start) and the
# coordinator runs with OPTICC_RACY_S=0.01 (on Linux the margin is derived from the clock; macOS uses 0.25 s).
set -u
B=${OPTICC_BUILD:-$(cd "$(dirname "$0")/../.." && pwd)/build}
OPTICC=$B/src/opticc/opticc; OPTICCD=$B/src/opticcd/opticcd
CC_REAL=${CC_REAL:-$(command -v clang || command -v cc)}   # clang preferred (Ubuntu cc = gcc: external as, other diagnostics)
T=$(mktemp -d /tmp/opticc-e2e-asm.XXXXXX)
fail() { echo "FAIL: $*"; cleanup; exit 1; }
cleanup() { [ -n "${WPID:-}" ] && kill "$WPID" 2>/dev/null; for p in $(lsof -t "$T/c.sock" 2>/dev/null); do kill "$p" 2>/dev/null; done; wait 2>/dev/null; }
trap cleanup EXIT

mkdir -p "$T/wkeys" "$T/ckeys"; "$OPTICC" keygen --dir "$T/ckeys" > /dev/null || fail "keygen"
cp "$T/ckeys/client.pub" "$T/wkeys/authorized_clients"; export OPTICC_KEY_DIR=$T/ckeys
"$OPTICCD" --listen 127.0.0.1:0 --jobs 4 --token e2e --key-dir "$T/wkeys" --tmp "$T/wtmp" > "$T/worker.out" 2> "$T/worker.err" & WPID=$!
for _ in $(seq 300); do grep -q listening "$T/worker.out" 2>/dev/null && break; sleep 0.1; done
PORT=$(sed -n 's/.*127.0.0.1:\([0-9]*\).*/\1/p' "$T/worker.out"); [ -n "$PORT" ] || fail "worker did not start: $(cat "$T/worker.err")"
PUB=$(sed -n 's/.*pubkey=\(.*\)$/\1/p' "$T/worker.out")
export OPTICC_SOCK=$T/c.sock OPTICC_HOSTS="127.0.0.1:$PORT#$PUB" OPTICC_TOKEN=e2e OPTICC_POLICY=ect-window OPTICC_MODE=header-push
export OPTICC_SUMMARY=$T/summary.json OPTICC_IDLE_TIMEOUT=600 OPTICC_LOCAL_SLOTS=0 OPTICC_LOCAL_CACHE=on OPTICC_LOCAL_CACHE_DIR=$T/lc
export OPTICC_DIRECT_TRACE=$T/trace.tsv OPTICC_RACY_S=0.01

fresh_summary() { local f=$1 pid=$2 m0; m0=$(python3 -c "import os,sys;print(os.stat(sys.argv[1]).st_mtime_ns if os.path.exists(sys.argv[1]) else 0)" "$f")
  kill -USR1 "$pid"; for _ in $(seq 600); do sleep 0.1; [ "$(python3 -c "import os,sys;print(os.stat(sys.argv[1]).st_mtime_ns if os.path.exists(sys.argv[1]) else 0)" "$f")" != "$m0" ] && break; done; sleep 0.1; }
summ() {   # field of the running coordinator's summary (python expression on s)
  local p; p=$(lsof -t "$OPTICC_SOCK" 2>/dev/null | head -1); [ -n "$p" ] || { echo 0; return; }
  fresh_summary "$T/summary.json" "$p"; python3 -c "import json;s=json.load(open('$T/summary.json'));print($1)"
}

S=$T/w; mkdir -p "$S/src/inc"
printf '#define VAL 5\n' > "$S/src/inc/defs.h"
printf '#include "defs.h"\n\t.data\n\t.globl sym_a\nsym_a:\n\t.long VAL\n\t.long VAL * 2\n' > "$S/src/a.S"
printf '\t.data\n\t.globl sym_bin\nsym_bin:\n\t.incbin "blob.bin"\n' > "$S/src/bin.S"
printf 'blob-v1\n' > "$S/src/blob.bin"
printf '\t.data\n\t.globl sym_inc\nsym_inc:\n\t.include "part.inc"\n' > "$S/src/inc.S"
printf '\t.long 3\n' > "$S/src/part.inc"
printf '#include "gen.h"\nint b(void) { return GEN; }\n' > "$S/src/b.c"
printf '#include "gen2.h"\nint c(void) { return GEN2; }\n' > "$S/src/c.c"
printf 'int d(int x) { return x * 3; }\n' > "$S/src/d.c"
cat > "$S/src/Makefile" <<'M'
DEP = -Wp,-MMD,$(@D)/.$(@F).d
all: a.o b.o c.o d.o g.o bin.o inc.o
gen.h: FORCE
	@rm -f gen.h; printf '#define GEN 42\n' > gen.h; sleep 0.05
gen2.h: FORCE
	@rm -f gen2.h; n=$$(cat counter 2>/dev/null || echo 0); n=$$((n+1)); echo $$n > counter; printf '#define GEN2 %d\n' $$n > gen2.h; sleep 0.05
g.S: FORCE
	@rm -f g.S; printf '\t.data\n\t.globl sym_g\nsym_g:\n\t.long 7\n\t.long 8\n' > g.S; sleep 0.05
b.o: b.c gen.h
	$(CC) -O2 $(DEP) -c b.c -o b.o
c.o: c.c gen2.h
	$(CC) -O2 $(DEP) -c c.c -o c.o
g.o: g.S
	$(CC) -c g.S -o g.o
%.o: %.S
	$(CC) $(DEP) -Iinc -c $< -o $@
%.o: %.c
	$(CC) -O2 $(DEP) -c $< -o $@
bin.o: blob.bin
inc.o: part.inc
clean:
	rm -f *.o .*.d gen.h gen2.h g.S
FORCE:
.PHONY: all clean FORCE
M
cp -r "$S/src" "$S/ref"; cp -r "$S/src" "$S/dist"; rm -rf "$S/src"
N=7
sleep 2.4   # the sources are older than any racy margin (the generated files are not: that is the point)

"$OPTICC" --coordinator > "$T/coord.out" 2> "$T/coord.err" &
for _ in $(seq 600); do [ -S "$OPTICC_SOCK" ] && break; sleep 0.05; done
[ -S "$OPTICC_SOCK" ] || fail "coordinator did not start: $(cat "$T/coord.err")"

step() {   # $1 label, $2 expected direct (wrapper) hits
  local lab=$1 want=$2 f0 f1
  ( cd "$S/ref" && make -s clean && make -s CC="$CC_REAL" ) > /dev/null 2>&1 || fail "$lab: reference build"
  f0=$(summ "s.get('client_fast_hits',0)")
  ( cd "$S/dist" && make -s clean && make -s CC="$OPTICC $CC_REAL" ) > "$S/out.txt" 2>&1 || fail "$lab: opticc build: $(cat "$S/out.txt")"
  f1=$(summ "s.get('client_fast_hits',0)")
  for o in "$S/ref"/*.o; do n=$(basename "$o"); cmp -s "$o" "$S/dist/$n" || fail "$lab: object differs: $n"; done
  for d in $(cd "$S/ref" && ls -a | grep '\.d$'); do cmp -s "$S/ref/$d" "$S/dist/$d" || fail "$lab: dep file differs: $d"; done
  [ "$(ls "$S/dist"/*.o | wc -l | tr -d ' ')" -eq "$N" ] || fail "$lab: missing objects"
  echo "$lab: direct hits $((f1 - f0))/$N, objects + dep files identical"
  [ "$((f1 - f0))" -eq "$want" ] || fail "$lab: expected $want direct hits, got $((f1 - f0)); trace: $(tail -20 "$T/trace.tsv")"
}
both() { for x in ref dist; do ( cd "$S/$x" && eval "$1" ); done; }

step "1 cold" 0
step "2 repeat (a.S, g.S, b.c, d.c hit; c.c regenerated differently; bin.S, inc.S never cached)" 4
both 'printf "#define VAL 6\n" > inc/defs.h'
step "3 assembler include edited (a.S misses)" 3
both 'printf "blob-v2\n" > blob.bin; printf "\t.long 4\n" > part.inc'
step "4 .incbin and .include inputs edited (bin.S, inc.S compiled again, new objects)" 4
step "5 repeat" 4
# the regenerated-identical inputs were recorded although they were minutes young, not seconds; the others not
grep -q "store-skipped.*bin.S" "$T/trace.tsv" || fail "trace: no store-skipped line for bin.S"
grep -q "store-skipped.*inc.S" "$T/trace.tsv" || fail "trace: no store-skipped line for inc.S"
grep -q "positive content: .*gen2.h" "$T/trace.tsv" || fail "trace: no content miss for gen2.h"
[ "$(summ "s['v4']['local_only_jobs']")" -gt 0 ] || fail "summary: no local-only (assembler) jobs"
grep -q "$(printf '\thit\t.*a.S')" "$T/trace.tsv" || fail "trace: a.S never hit in the wrapper"
grep -q "$(printf '\thit\t.*g.S')" "$T/trace.tsv" || fail "trace: the generated g.S never hit in the wrapper"
echo "ok: trace $(grep -c "$(printf '\thit\t')" "$T/trace.tsv") hits, $(grep -c "$(printf '\tmiss\t')" "$T/trace.tsv") misses, $(grep -c -- '-skipped' "$T/trace.tsv") skipped"
echo "E2E-ASM-REGEN PASS ($T)"
cleanup; trap - EXIT; rm -rf "$T"; exit 0
